export function parseJD(text,title=""){const body=norm(text),heading=norm(title),skills=[];for(const [skill,aliases] of Object.entries(SKILLS))if(has(body,aliases))skills.push(skill);const preferred=new Set();for(const sentence of body.split(/[\n.!?]+/))if(/preferred|nice to have|bonus|plus/.test(sentence))for(const [skill,aliases] of Object.entries(SKILLS))if(has(sentence,aliases))preferred.add(skill);const years=[...body.matchAll(/(?:at least|minimum(?: of)?|requires?|with)?\s*(\d+)\+?\s*(?:years?|yrs?)(?:\s+of)?\s+(?:professional\s+)?experience/g)].map(x=>Number(x[1]));return{required:skills.filter(x=>!preferred.has(x)),preferred:[...preferred],minYears:years.length?Math.min(...years):0,seniority:/\b(principal|staff)\b/.test(heading)?"staff":/\bsenior\b/.test(heading)?"senior":/\b(intern|internship)\b/.test(heading)?"intern":/\b(new grad|early career|entry.level|associate|junior)\b/.test(`${heading} ${body}`)?"early-career":"unspecified",domains:Object.entries(DOMAINS).filter(([,a])=>has(body,a)).map(([d])=>d),workSetting:/\bremote\b/.test(body)?"remote":/\bhybrid\b/.test(body)?"hybrid":/\bon[ -]?site\b/.test(body)?"onsite":"unspecified",sensitive:/(visa|sponsor|work authori[sz]ation|citizen|permanent resident|green card|opt\b|f-1|legal right to work)/i.test(text)}}
